def apply(inputs, premises):
    checked_dimensions = []
    checked_weights = []
    personal_used = False
    carry_on_used = False
    for i in range(len(inputs["item_dimension_sums"])):
        if inputs["personal_item_eligible"][i] and not personal_used:
            personal_used = True
        elif inputs["carry_on_eligible"][i] and not carry_on_used:
            carry_on_used = True
        else:
            checked_dimensions = checked_dimensions + [inputs["item_dimension_sums"][i]]
            checked_weights = checked_weights + [inputs["item_weights"][i]]
    fee_total = 0
    for i in range(len(checked_dimensions)):
        if i == 0:
            base_fee = inputs["first_checked_bag_fee"]
        elif i == 1:
            base_fee = inputs["second_checked_bag_fee"]
        elif i == 2:
            base_fee = inputs["third_checked_bag_fee"]
        else:
            base_fee = inputs["fourth_plus_checked_bag_fee"]
        dimension = checked_dimensions[i]
        oversize_fee = 0
        if dimension > 62:
            if dimension <= 65:
                oversize_fee = inputs["oversize_63_to_65_fee"]
            else:
                oversize_fee = inputs["oversize_over_65_fee"]
        weight = checked_weights[i]
        overweight_fee = 0
        elevated_allowance = i < inputs["complimentary_70lb_bag_count"]
        if not elevated_allowance or weight > 70:
            if weight > 50 and weight <= 53:
                overweight_fee = inputs["overweight_51_to_53_fee"]
            elif weight > 53 and weight <= 70:
                overweight_fee = inputs["overweight_54_to_70_fee"]
            elif weight > 70:
                overweight_fee = inputs["overweight_over_70_fee"]
        if premises["use_higher_excess_fee"]:
            excess_fee = max(oversize_fee, overweight_fee)
        else:
            excess_fee = oversize_fee + overweight_fee
        fee_total = fee_total + base_fee + excess_fee
    answer = int(inputs["ticket_price"] + fee_total)
    return {"answer": answer}

def apply(inputs, premises):
    in_bracket = inputs["taxable_income"] > inputs["cited_bracket_lower_exclusive"]
    if inputs["cited_bracket_upper_inclusive"] >= 0:
        in_bracket = in_bracket and inputs["taxable_income"] <= inputs["cited_bracket_upper_inclusive"]
    expected_tax = inputs["cited_bracket_base_tax"] + inputs["cited_bracket_rate_percent"] * (inputs["taxable_income"] - inputs["cited_bracket_excess_threshold"]) / 100
    amount_matches = round(expected_tax, 2) == round(inputs["claimed_tax_amount"], 2)
    statement_true = in_bracket and amount_matches
    entailed = statement_true == inputs["claim_affirms_exact_tax"]
    if entailed:
        answer = "Entailment"
    else:
        answer = "Contradiction"
    return {"answer": answer}
